import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { reportsService } from '../services/api';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  Cell 
} from 'recharts';
import { 
  BarChart3, 
  FileText, 
  Download, 
  AlertCircle, 
  ShieldCheck, 
  Heart, 
  Zap, 
  Baby, 
  TrendingUp,
  Droplets,
  Wallet,
  Activity
} from 'lucide-react';
import toast from 'react-hot-toast';

const REPORT_TYPES = {
  animals_inventory: 'Hayvan Envanteri',
  health_summary: 'Sağlık Özeti',
  production: 'Üretim Raporu',
  financial: 'Finansal Rapor',
  reproduction: 'Üreme Raporu'
};

const CHART_COLORS = ['#0d9488', '#0284c7', '#f59e0b', '#ef4444', '#8b5cf6', '#10b981'];

export default function ReportsPage() {
  const { user } = useAuth();
  const farmId = user?.farm_id;

  const [reportType, setReportType] = useState('animals_inventory');
  const [period, setPeriod] = useState(new Date().toISOString().slice(0, 7));
  const [loading, setLoading] = useState(false);
  const [pdfLoading, setPdfLoading] = useState(false);
  const [reportData, setReportData] = useState(null);

  const handleGenerateReport = async () => {
    if (!farmId) {
      toast.error('Çiftlik bilgisi bulunamadı');
      return;
    }
    if (!reportType || !period) {
      toast.error('Rapor türü ve dönem seçimi gerekli');
      return;
    }

    setLoading(true);
    try {
      const res = await reportsService.generate(farmId, {
        report_type: reportType,
        period: period
      });
      setReportData(res?.data?.data || null);
      toast.success('Rapor başarıyla oluşturuldu');
    } catch (err) {
      toast.error(err.response?.data?.error || 'Rapor oluşturulamadı');
    } finally {
      setLoading(false);
    }
  };

  const handleExportPDF = async () => {
    if (!farmId) {
      toast.error('Çiftlik bilgisi bulunamadı');
      return;
    }
    if (!reportType || !period) {
      toast.error('Rapor türü ve dönem seçimi gerekli');
      return;
    }

    setPdfLoading(true);
    try {
      const res = await reportsService.generatePDF(farmId, {
        report_type: reportType,
        period: period
      });
      
      const blob = new Blob([res.data], { type: 'application/pdf' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `mfk-farm-rapor-${reportType}-${period}.pdf`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
      
      toast.success('PDF raporu başarıyla indirildi');
    } catch (err) {
      toast.error(err.response?.data?.error || 'PDF indirilemedi');
    } finally {
      setPdfLoading(false);
    }
  };

  // Helper chart data generators
  const getAnimalChartData = () => {
    if (!reportData?.animals?.by_type) return [];
    const t = reportData.animals.by_type;
    return [
      { name: 'Keçi', count: t.keci ?? 0 },
      { name: 'Koyun', count: t.koyun ?? 0 },
      { name: 'Sığır', count: t.sigir ?? 0 },
      { name: 'Manda', count: t.manda ?? 0 },
      { name: 'Deve', count: t.deve ?? 0 },
    ];
  };

  const getHealthChartData = () => {
    if (!reportData?.health?.by_type) return [];
    const h = reportData.health.by_type;
    return [
      { name: 'Aşı', count: h.vaccination ?? 0 },
      { name: 'Hastalık', count: h.disease ?? 0 },
      { name: 'İlaç/Tedavi', count: h.medication ?? 0 },
      { name: 'Muayene', count: h.examination ?? 0 },
    ];
  };

  const getFinancialChartData = () => {
    if (!reportData?.financial) return [];
    const inc = Number(reportData.financial.income) || 0;
    const exp = Number(reportData.financial.expense) || 0;
    const prf = Number(reportData.financial.profit ?? (inc - exp));
    return [
      { name: 'Gelir', tutar: inc, fill: '#10b981' },
      { name: 'Gider', tutar: exp, fill: '#ef4444' },
      { name: 'Net Kâr', tutar: Math.max(0, prf), fill: '#0ea5e9' }
    ];
  };

  const getReproductionChartData = () => {
    if (!reportData?.reproduction) return [];
    const r = reportData.reproduction;
    return [
      { name: 'Kızgınlık', count: r.estrus_count ?? 0 },
      { name: 'Tohumlama', count: r.mating_count ?? 0 },
      { name: 'Doğum', count: r.birth_count ?? 0 },
    ];
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto">
      {/* Başlık Alanı */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold" style={{ color: 'var(--text)' }}>📊 Raporlama Merkezi</h1>
          <p className="text-sm mt-1" style={{ color: 'var(--text-secondary)' }}>
            Çiftlik performansı, üretim ve finansal analizler
          </p>
        </div>
      </div>

      {/* Rapor Seçim Kartı */}
      <div className="card border border-teal-100 bg-teal-50/20 p-4 sm:p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-2 ml-1">Rapor Türü Seçin</label>
              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-1 gap-2">
                {Object.entries(REPORT_TYPES).map(([key, label]) => (
                  <button
                    key={key}
                    onClick={() => {
                      setReportType(key);
                      setReportData(null);
                    }}
                    className={`flex items-center gap-3 p-3 rounded-2xl text-sm font-bold transition-all border ${
                      reportType === key 
                      ? 'bg-teal-700 text-white border-teal-700 shadow-md shadow-teal-700/20 scale-[1.01]' 
                      : 'bg-white text-gray-700 border-gray-100 hover:border-teal-300'
                    }`}
                  >
                    <div className={`p-2 rounded-xl ${reportType === key ? 'bg-white/20' : 'bg-teal-50 text-teal-700'}`}>
                      <FileText className="w-4 h-4" />
                    </div>
                    <span>{label}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-6 flex flex-col justify-between">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-2 ml-1">Rapor Dönemi (Ay / Yıl)</label>
              <input
                type="month"
                value={period}
                onChange={e => setPeriod(e.target.value)}
                className="input-field text-base sm:text-lg font-bold py-3 w-full bg-white"
              />
              <p className="text-xs text-gray-400 mt-2 ml-1">
                Seçtiğiniz ayın başlangıcından son gününe kadar olan veriler taranır.
              </p>
            </div>

            <div className="space-y-3 pt-2">
              <button
                onClick={handleGenerateReport}
                disabled={loading}
                className="btn-primary w-full flex items-center justify-center gap-2 py-3.5 shadow-md shadow-teal-700/20 font-bold"
              >
                {loading ? (
                  <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                ) : (
                  <><BarChart3 className="w-5 h-5" /> Raporu Hazırla</>
                )}
              </button>
              <button
                onClick={handleExportPDF}
                disabled={pdfLoading || loading}
                className="btn-secondary w-full flex items-center justify-center gap-2 py-3.5 bg-white border border-gray-200 hover:bg-gray-50 text-gray-800 font-bold"
              >
                {pdfLoading ? (
                  <div className="w-5 h-5 border-2 border-gray-500 border-t-transparent rounded-full animate-spin" />
                ) : (
                  <><Download className="w-5 h-5 text-teal-600" /> Resmi PDF İndir</>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Rapor İçeriği */}
      {reportData && (
        <div className="card animate-in fade-in slide-in-from-bottom-4 p-4 sm:p-6 bg-white border border-gray-100">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between pb-4 border-b border-gray-100 gap-2 mb-6">
            <h2 className="text-lg sm:text-xl font-black text-gray-900 flex items-center gap-2">
              <span>{REPORT_TYPES[reportType]}</span>
              <span className="text-teal-700 font-bold text-sm bg-teal-50 px-2.5 py-1 rounded-full border border-teal-100">
                {period}
              </span>
            </h2>
            <div className="flex items-center gap-2">
              <button
                onClick={handleExportPDF}
                disabled={pdfLoading}
                className="text-xs font-bold text-teal-700 hover:text-teal-800 flex items-center gap-1.5 py-1.5 px-3 rounded-xl bg-teal-50 hover:bg-teal-100 transition-colors"
              >
                <Download className="w-3.5 h-3.5" /> PDF Al
              </button>
            </div>
          </div>

          {/* Hayvan Envanteri */}
          {reportType === 'animals_inventory' && reportData.animals && (
            <div className="space-y-6">
              {/* Metrik Kartları */}
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 sm:gap-4">
                {[
                  { label: 'Toplam Sürü', count: reportData.animals.total ?? 0, bg: '#eff6ff', border: '#dbeafe', text: '#2563eb', textDark: '#1d4ed8' },
                  { label: 'Keçi', count: reportData.animals.by_type?.keci ?? 0, bg: '#ecfdf5', border: '#d1fae5', text: '#059669', textDark: '#047857' },
                  { label: 'Koyun', count: reportData.animals.by_type?.koyun ?? 0, bg: '#fff7ed', border: '#ffedd5', text: '#ea580c', textDark: '#c2410c' },
                  { label: 'Sığır', count: reportData.animals.by_type?.sigir ?? 0, bg: '#fef2f2', border: '#fee2e2', text: '#dc2626', textDark: '#b91c1c' },
                  { label: 'Manda', count: reportData.animals.by_type?.manda ?? 0, bg: '#faf5ff', border: '#f3e8ff', text: '#9333ea', textDark: '#7e22ce' },
                  { label: 'Deve', count: reportData.animals.by_type?.deve ?? 0, bg: '#fffbeb', border: '#fef3c7', text: '#d97706', textDark: '#b45309' },
                ].map((item, i) => (
                  <div key={i} className="card text-center p-3 sm:p-4 shadow-none border" style={{ backgroundColor: item.bg, borderColor: item.border }}>
                    <p className="text-[10px] sm:text-xs font-black uppercase tracking-wider" style={{ color: item.text }}>{item.label}</p>
                    <p className="text-xl sm:text-2xl font-black mt-1" style={{ color: item.textDark }}>{item.count}</p>
                  </div>
                ))}
              </div>

              {/* Tür Grafiği */}
              <div className="p-4 sm:p-6 bg-gray-50/50 rounded-3xl border border-gray-100">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="font-bold text-gray-900 text-sm sm:text-base flex items-center gap-2">
                    <Activity className="w-4 h-4 text-teal-600" /> Sürü Tür Dağılım Grafiği
                  </h3>
                  <span className="text-xs text-gray-400">Baş sayısı</span>
                </div>
                <div className="w-full min-w-0 h-[240px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={getAnimalChartData()}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                      <XAxis dataKey="name" tick={{ fontSize: 12, fill: '#64748b' }} axisLine={false} tickLine={false} />
                      <YAxis allowDecimals={false} tick={{ fontSize: 12, fill: '#64748b' }} axisLine={false} tickLine={false} width={30} />
                      <Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0' }} />
                      <Bar dataKey="count" name="Hayvan Sayısı" radius={[8, 8, 0, 0]}>
                        {getAnimalChartData().map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={CHART_COLORS[index % CHART_COLORS.length]} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* Durum Dağılımı */}
              {reportData.animals.by_status && (
                <div className="bg-gray-50/50 p-4 sm:p-6 rounded-3xl border border-gray-100">
                  <h3 className="font-bold text-gray-900 mb-4 text-sm sm:text-base">Durum Dağılımı</h3>
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                    {Object.entries(reportData.animals.by_status).map(([status, count]) => (
                      <div key={status} className="flex items-center justify-between p-3.5 bg-white rounded-2xl border border-gray-100 shadow-xs">
                        <span className="text-xs font-bold text-gray-500 uppercase">
                          {status === 'active' ? 'Aktif' : status === 'dead' ? 'Ölü / Zayiat' : status === 'sold' ? 'Satılmış' : 'Kayıp'}
                        </span>
                        <span className="text-base sm:text-lg font-black text-gray-900">{count ?? 0}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Sağlık Özeti */}
          {reportType === 'health_summary' && reportData.health && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="card flex items-center gap-4 bg-red-50/60 border border-red-100 p-5 shadow-none rounded-2xl">
                  <div className="p-3 bg-red-500 rounded-2xl shadow-md shadow-red-500/20 text-white">
                    <AlertCircle className="w-6 h-6" />
                  </div>
                  <div>
                    <p className="text-red-700 text-xs font-black uppercase tracking-wider">Hastalık Kaydı</p>
                    <p className="text-2xl sm:text-3xl font-black text-red-900">{reportData.health.by_type?.disease ?? 0}</p>
                  </div>
                </div>
                <div className="card flex items-center gap-4 bg-teal-50/60 border border-teal-100 p-5 shadow-none rounded-2xl">
                  <div className="p-3 bg-teal-600 rounded-2xl shadow-md shadow-teal-600/20 text-white">
                    <ShieldCheck className="w-6 h-6" />
                  </div>
                  <div>
                    <p className="text-teal-700 text-xs font-black uppercase tracking-wider">Aşı Kaydı</p>
                    <p className="text-2xl sm:text-3xl font-black text-teal-900">{reportData.health.by_type?.vaccination ?? 0}</p>
                  </div>
                </div>
              </div>

              {/* Sağlık İşlem Dağılım Grafiği */}
              <div className="p-4 sm:p-6 bg-gray-50/50 rounded-3xl border border-gray-100">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="font-bold text-gray-900 text-sm sm:text-base flex items-center gap-2">
                    <ShieldCheck className="w-4 h-4 text-teal-600" /> Sağlık İşlemleri Dağılımı
                  </h3>
                  <span className="text-xs text-gray-400">İşlem adedi</span>
                </div>
                <div className="w-full min-w-0 h-[220px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={getHealthChartData()}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                      <XAxis dataKey="name" tick={{ fontSize: 12, fill: '#64748b' }} axisLine={false} tickLine={false} />
                      <YAxis allowDecimals={false} tick={{ fontSize: 12, fill: '#64748b' }} axisLine={false} tickLine={false} width={30} />
                      <Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0' }} />
                      <Bar dataKey="count" name="Kayıt Sayısı" radius={[8, 8, 0, 0]}>
                        <Cell fill="#0d9488" />
                        <Cell fill="#ef4444" />
                        <Cell fill="#f59e0b" />
                        <Cell fill="#0284c7" />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>

              {/* Kritik Kayıtlar */}
              {reportData.health.records && reportData.health.records.length > 0 && (
                <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-xs">
                  <div className="px-5 py-3 border-b bg-gray-50/70">
                    <h3 className="font-bold text-gray-900 text-sm">Son Sağlık ve Tedavi Kayıtları</h3>
                  </div>
                  <div className="divide-y divide-gray-100 max-h-72 overflow-y-auto">
                    {reportData.health.records.slice(0, 10).map((r, idx) => (
                      <div key={idx} className="p-3 sm:p-4 hover:bg-gray-50 transition-colors flex justify-between items-center gap-3">
                        <div className="min-w-0">
                          <p className="font-bold text-gray-900 text-xs sm:text-sm truncate">{r.description || 'Açıklama belirtilmemiş'}</p>
                          <p className="text-[11px] text-gray-500 font-medium mt-0.5">{r.record_date} • Hayvan #{r.animal_id}</p>
                        </div>
                        <span className="text-[11px] font-bold text-gray-500 bg-gray-100 px-2 py-1 rounded-lg flex-shrink-0">
                          #{idx + 1}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Üretim Raporu */}
          {reportType === 'production' && reportData.production && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="card bg-teal-50/50 border border-teal-100 p-6 sm:p-8 text-center shadow-none rounded-2xl">
                  <div className="w-12 h-12 bg-teal-600 rounded-full flex items-center justify-center text-white mx-auto mb-3 shadow-md shadow-teal-600/20">
                    <Droplets className="w-6 h-6" />
                  </div>
                  <p className="text-teal-800 text-xs font-black uppercase tracking-wider mb-1">Dönem Toplam Süt Üretimi</p>
                  <p className="text-3xl sm:text-5xl font-black text-teal-900">
                    {Number(reportData.production.total_milk || 0).toLocaleString('tr-TR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} <span className="text-lg sm:text-xl font-bold">Litre</span>
                  </p>
                </div>
                <div className="card bg-emerald-50/50 border border-emerald-100 p-6 sm:p-8 text-center shadow-none rounded-2xl">
                  <div className="w-12 h-12 bg-emerald-600 rounded-full flex items-center justify-center text-white mx-auto mb-3 shadow-md shadow-emerald-600/20">
                    <TrendingUp className="w-6 h-6" />
                  </div>
                  <p className="text-emerald-800 text-xs font-black uppercase tracking-wider mb-1">Günlük Ortalama Verim</p>
                  <p className="text-3xl sm:text-5xl font-black text-emerald-900">
                    {Number(reportData.production.avg_daily || 0).toLocaleString('tr-TR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} <span className="text-lg sm:text-xl font-bold">L/Gün</span>
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Finansal Rapor */}
          {reportType === 'financial' && reportData.financial && (() => {
            const income = Number(reportData.financial.income) || 0;
            const expense = Number(reportData.financial.expense) || 0;
            const profit = Number(reportData.financial.profit ?? (income - expense));
            return (
              <div className="space-y-6">
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <div className="card bg-emerald-50/50 border-l-4 border-emerald-500 p-5 shadow-none rounded-2xl">
                    <p className="text-emerald-700 text-xs font-black uppercase tracking-wider">Aylık Toplam Gelir</p>
                    <p className="text-2xl sm:text-3xl font-black text-emerald-900 mt-1">
                      ₺{income.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </p>
                  </div>
                  <div className="card bg-red-50/50 border-l-4 border-red-500 p-5 shadow-none rounded-2xl">
                    <p className="text-red-700 text-xs font-black uppercase tracking-wider">Aylık Toplam Gider</p>
                    <p className="text-2xl sm:text-3xl font-black text-red-900 mt-1">
                      ₺{expense.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </p>
                  </div>
                  <div className={`card ${profit >= 0 ? 'bg-teal-50/50 border-teal-500' : 'bg-orange-50/50 border-orange-500'} border-l-4 p-5 shadow-none rounded-2xl`}>
                    <p className="text-gray-500 text-xs font-black uppercase tracking-wider">Net Kar / Zarar</p>
                    <p className={`text-2xl sm:text-3xl font-black mt-1 ${profit >= 0 ? 'text-teal-900' : 'text-orange-900'}`}>
                      {profit >= 0 ? '+' : ''}₺{profit.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </p>
                  </div>
                </div>

                {/* Finans Karşılaştırma Grafiği */}
                <div className="p-4 sm:p-6 bg-gray-50/50 rounded-3xl border border-gray-100">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="font-bold text-gray-900 text-sm sm:text-base flex items-center gap-2">
                      <Wallet className="w-4 h-4 text-teal-600" /> Finansal Denge Grafiği
                    </h3>
                    <span className="text-xs text-gray-400">TL Bazında</span>
                  </div>
                  <div className="w-full min-w-0 h-[220px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={getFinancialChartData()}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                        <XAxis dataKey="name" tick={{ fontSize: 12, fill: '#64748b' }} axisLine={false} tickLine={false} />
                        <YAxis tick={{ fontSize: 11, fill: '#64748b' }} axisLine={false} tickLine={false} width={60} tickFormatter={v => `₺${v}`} />
                        <Tooltip 
                          formatter={(value) => [`₺${Number(value).toLocaleString('tr-TR')}`, 'Tutar']}
                          contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0' }} 
                        />
                        <Bar dataKey="tutar" name="Miktar" radius={[8, 8, 0, 0]}>
                          {getFinancialChartData().map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={entry.fill} />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              </div>
            );
          })()}

          {/* Üreme Raporu */}
          {reportType === 'reproduction' && reportData.reproduction && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div className="card bg-pink-50/50 border border-pink-100 text-center p-5 shadow-none rounded-2xl">
                  <div className="w-10 h-10 bg-pink-500 rounded-full flex items-center justify-center text-white mx-auto mb-2 shadow-md shadow-pink-500/20">
                    <Heart className="w-5 h-5" />
                  </div>
                  <p className="text-pink-700 text-xs font-black uppercase tracking-wider">Kızgınlık Kaydı</p>
                  <p className="text-2xl sm:text-3xl font-black text-pink-900 mt-1">{reportData.reproduction.estrus_count ?? 0}</p>
                </div>
                <div className="card bg-indigo-50/50 border border-indigo-100 text-center p-5 shadow-none rounded-2xl">
                  <div className="w-10 h-10 bg-indigo-500 rounded-full flex items-center justify-center text-white mx-auto mb-2 shadow-md shadow-indigo-500/20">
                    <Zap className="w-5 h-5" />
                  </div>
                  <p className="text-indigo-700 text-xs font-black uppercase tracking-wider">Tohumlama / Çiftleşme</p>
                  <p className="text-2xl sm:text-3xl font-black text-indigo-900 mt-1">{reportData.reproduction.mating_count ?? 0}</p>
                </div>
                <div className="card bg-amber-50/50 border border-amber-100 text-center p-5 shadow-none rounded-2xl">
                  <div className="w-10 h-10 bg-amber-500 rounded-full flex items-center justify-center text-white mx-auto mb-2 shadow-md shadow-amber-500/20">
                    <Baby className="w-5 h-5" />
                  </div>
                  <p className="text-amber-700 text-xs font-black uppercase tracking-wider">Doğum Kaydı</p>
                  <p className="text-2xl sm:text-3xl font-black text-amber-900 mt-1">{reportData.reproduction.birth_count ?? 0}</p>
                </div>
              </div>

              {/* Üreme Grafiği */}
              <div className="p-4 sm:p-6 bg-gray-50/50 rounded-3xl border border-gray-100">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="font-bold text-gray-900 text-sm sm:text-base flex items-center gap-2">
                    <Baby className="w-4 h-4 text-teal-600" /> Üreme ve Döl Faaliyetleri
                  </h3>
                  <span className="text-xs text-gray-400">Adet</span>
                </div>
                <div className="w-full min-w-0 h-[220px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={getReproductionChartData()}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
                      <XAxis dataKey="name" tick={{ fontSize: 12, fill: '#64748b' }} axisLine={false} tickLine={false} />
                      <YAxis allowDecimals={false} tick={{ fontSize: 12, fill: '#64748b' }} axisLine={false} tickLine={false} width={30} />
                      <Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #e2e8f0' }} />
                      <Bar dataKey="count" name="Adet" radius={[8, 8, 0, 0]}>
                        <Cell fill="#ec4899" />
                        <Cell fill="#6366f1" />
                        <Cell fill="#f59e0b" />
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Bilgi Kutusu */}
      {!reportData && (
        <div className="card bg-teal-50/40 border-l-4 border-teal-600 p-4 sm:p-5 rounded-2xl">
          <p className="text-teal-900 text-sm font-medium">
            💡 Rapor türü ve dönemi seçerek "Raporu Hazırla" butonuna tıklayın. Çiftliğinize ait tüm veriler hesaplanarak görsel grafiklerle birlikte listelenecektir.
          </p>
        </div>
      )}
    </div>
  );
}
